// ============================================================
// Nœud Code n8n : calcul des objectifs journaliers
// Mode : "Run Once for All Items"   Langage : JavaScript
// Traduction fidèle de calcul_objectifs.py (le Python reste la référence).
// ============================================================

const e = $input.first().json.body || {};

// ---------- Paramètres (identiques au Python) ----------
const FACTEURS_ACTIVITE = { sedentaire: 1.2, leger: 1.375, modere: 1.55, actif: 1.725 };
const OBJECTIFS = ['perte', 'maintien', 'prise'];
const DEFICIT_PERTE = 0.20;
const DEFICIT_MAX_KCAL = 500;
const SURPLUS_PRISE = 0.10;
const PROT_G_PAR_KG_PERTE = 1.8;
const PROT_G_PAR_KG_AUTRE = 1.6;
const PROT_G_PAR_KG_MIN = 1.4;
const LIPIDES_PART = 0.25;
const LIPIDES_PART_MIN = 0.20;
const GLUCIDES_PART_MIN = 0.45;
const GLUCIDES_PART_MAX = 0.65;
const PROT_PART_MAX = 0.35;
const IMC_MIN_POUR_PERTE = 18.5;
const SEUIL_KCAL_BAS = { F: 1200, H: 1500 }; // à confirmer sur une source officielle
const AGE_MIN = 18, AGE_MAX = 100;
const TAILLE_MIN = 120, TAILLE_MAX = 230;
const POIDS_MIN = 30, POIDS_MAX = 300;

const arrondi = (x) => Math.floor(x + 0.5);

// ---------- Validation ----------
function verifierNombre(nom, v, min, max) {
  if (typeof v !== 'number' || !Number.isFinite(v)) return `${nom} doit être un nombre.`;
  if (v < min || v > max) return `${nom} doit être compris entre ${min} et ${max}.`;
  return null;
}

function valider(e) {
  let err =
    verifierNombre("L'âge", e.age, AGE_MIN, AGE_MAX) ||
    (e.sexe !== 'H' && e.sexe !== 'F' ? "Le sexe doit être 'H' ou 'F'." : null) ||
    verifierNombre('La taille (cm)', e.taille_cm, TAILLE_MIN, TAILLE_MAX) ||
    verifierNombre('Le poids (kg)', e.poids_kg, POIDS_MIN, POIDS_MAX) ||
    (!(e.activite in FACTEURS_ACTIVITE)
      ? `Niveau d'activité inconnu : choisir parmi ${Object.keys(FACTEURS_ACTIVITE).sort().join(', ')}.`
      : null) ||
    (!OBJECTIFS.includes(e.objectif)
      ? `Objectif inconnu : choisir parmi ${OBJECTIFS.join(', ')}.`
      : null);
  if (err) return err;

  const imc = e.poids_kg / Math.pow(e.taille_cm / 100, 2);
  if (e.objectif === 'perte' && imc < IMC_MIN_POUR_PERTE) {
    return `Objectif de perte refusé : IMC de ${imc.toFixed(1)}, inférieur à ${IMC_MIN_POUR_PERTE}.`;
  }
  return null;
}

// ---------- Calcul ----------
const erreur = valider(e);
if (erreur) {
  return [{ json: { ok: false, erreur } }];
}

// 1. Métabolisme de base (Mifflin-St Jeor)
const base = 10 * e.poids_kg + 6.25 * e.taille_cm - 5 * e.age;
const bmr = e.sexe === 'H' ? base + 5 : base - 161;

// 2. Dépense totale
const tdee = bmr * FACTEURS_ACTIVITE[e.activite];

// 3. Objectif calorique
const avertissements = [];
let kcal;
if (e.objectif === 'perte') {
  const deficit = Math.min(DEFICIT_PERTE * tdee, DEFICIT_MAX_KCAL);
  kcal = tdee - deficit;
  if (kcal < bmr) {
    kcal = bmr;
    avertissements.push('Objectif relevé au niveau du métabolisme de base (plancher de sécurité).');
  }
} else if (e.objectif === 'prise') {
  kcal = tdee * (1 + SURPLUS_PRISE);
} else {
  kcal = tdee;
}

// 4. Répartition des macronutriments
const ratio = e.objectif === 'perte' ? PROT_G_PAR_KG_PERTE : PROT_G_PAR_KG_AUTRE;
let protKcal = Math.min(ratio * e.poids_kg * 4, PROT_PART_MAX * kcal);
let lipKcal = LIPIDES_PART * kcal;
let glucKcal = kcal - protKcal - lipKcal;

if (glucKcal < GLUCIDES_PART_MIN * kcal) {
  glucKcal = GLUCIDES_PART_MIN * kcal;
  protKcal = kcal - lipKcal - glucKcal;                 // 1) on baisse les protéines
  const protMinKcal = PROT_G_PAR_KG_MIN * e.poids_kg * 4;
  if (protKcal < protMinKcal) {                         // 2) puis les lipides
    protKcal = protMinKcal;
    lipKcal = Math.max(kcal - protKcal - glucKcal, LIPIDES_PART_MIN * kcal);
    glucKcal = kcal - protKcal - lipKcal;
    if (glucKcal < GLUCIDES_PART_MIN * kcal) {
      avertissements.push("Glucides sous 45 % de l'énergie malgré les corrections.");
    }
  } else {
    avertissements.push("Protéines réduites pour respecter la plage des glucides (45 % minimum).");
  }
}
if (glucKcal > GLUCIDES_PART_MAX * kcal) {
  avertissements.push("Glucides au-dessus de 65 % de l'énergie.");
}
if (kcal < SEUIL_KCAL_BAS[e.sexe]) {
  avertissements.push("Objectif calorique très bas : avis d'un professionnel de santé recommandé.");
}

// 5. Résultat (noms alignés sur les colonnes de la table users)
return [{
  json: {
    ok: true,
    user: {
      age: e.age,
      sexe: e.sexe,
      taille_cm: e.taille_cm,
      poids_kg: e.poids_kg,
      activite: e.activite,
      objectif: e.objectif,
      kcal_cible: arrondi(kcal),
      prot_cible: arrondi(protKcal / 4),
      gluc_cible: arrondi(glucKcal / 4),
      lip_cible: arrondi(lipKcal / 9),
    },
    details: {
      bmr: Math.round(bmr * 100) / 100,
      tdee: Math.round(tdee * 100) / 100,
      gluc_pourcent: Math.round((1000 * glucKcal) / kcal) / 10,
    },
    avertissements,
  },
}];

const calcul = $('Calcul objectifs').first().json;
const enregistre = $input.first().json;

return [{
  json: {
    ok: true,
    user_id: enregistre.id,
    objectifs: {
      kcal: calcul.user.kcal_cible,
      prot: calcul.user.prot_cible,
      gluc: calcul.user.gluc_cible,
      lip: calcul.user.lip_cible,
    },
    avertissements: calcul.avertissements,
  },
}];
